import { MeshBasicNodeMaterial } from 'three/webgpu';
import {
  uv,
  vec2,
  vec3,
  mix,
  color,
  sin,
  dot,
  fract,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, Color } = THREE;

  const group = new Group();
  group.name = 'pricing-title';

  const palette = (config.intent?.visualSpec?.colors) ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const disposables = [];
  let loadedTexture = null;

  // ---- 1. Engineered gradient backdrop (static composition, subtle grain) ----
  const backdropW = 2.8;
  const backdropH = 1.35;
  const backdropGeo = new PlaneGeometry(backdropW, backdropH);
  const backdropMat = new MeshBasicNodeMaterial({ transparent: false });

  const topC = color(palette.ink);
  const bottomC = color(palette.surface);
  const gradient = mix(bottomC, topC, uv().y);

  const grainSeed = dot(uv(), vec2(12.9898, 78.233));
  const grain = fract(sin(grainSeed).mul(43758.5453));
  const grainSigned = grain.sub(0.5).mul(0.035);
  const grainVec = vec3(grainSigned, grainSigned, grainSigned);

  backdropMat.colorNode = gradient.add(grainVec);

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -0.06);
  group.add(backdrop);
  disposables.push(() => backdropGeo.dispose(), () => backdropMat.dispose());

  // ---- 2. Isolated hero image plane (secondary depth layer) ----
  const imgW = 2.0;
  const imgH = imgW * (320 / 512);
  const imgGeo = new PlaneGeometry(imgW, imgH);
  const imgMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 0.85 });
  const imgMesh = new Mesh(imgGeo, imgMat);
  imgMesh.position.set(0, -0.02, -0.03);
  group.add(imgMesh);
  disposables.push(() => imgGeo.dispose(), () => imgMat.dispose());

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      imgMat.map = tex;
      imgMat.needsUpdate = true;
    }).catch(() => {});
  }

  // ---- 3. Headline text "Pricing" via MSDF font atlas ----
  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem =
    items.find((i) => i.role === 'headline') ?? items[0] ?? { text: 'Pricing' };

  const headline = ctx.fontAtlas.createText(headlineItem.text, {
    fontSize: headlineItem.typography?.fontSize ?? 96,
    color: palette.paper,
    align: 'center',
  });
  headline.position.set(0, 0.06, 0.05);
  group.add(headline);

  // ---- 4. Accent underline (one small, restrained accent element) ----
  const lineGeo = new PlaneGeometry(0.72, 0.035);
  const lineMat = new MeshBasicNodeMaterial({
    color: new Color(palette.accent),
  });
  const line = new Mesh(lineGeo, lineMat);
  line.position.set(0, -0.32, 0.05);
  group.add(line);
  disposables.push(() => lineGeo.dispose(), () => lineMat.dispose());

  // ---- 5. Weighted-settle entrance (static composition, one-time motion) ----
  group.scale.set(0.96, 0.96, 0.96);
  group.position.y += 0.0;
  const initialY = group.position.y;
  group.position.y = initialY + 0.3;

  const tl = gsap.timeline();
  tl.to(group.position, {
    y: initialY,
    duration: 0.7,
    ease: 'power3.out',
  });
  tl.to(
    group.scale,
    {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.9,
      ease: 'power4.out',
    },
    0.05
  );

  // ---- 6. Primitives (none configured for this node) ----
  const primitiveHandles = [];
  const prims = config.cinematicPrimitives ?? [];
  for (const prim of prims) {
    const fn = ctx.primitives[prim.name];
    if (fn) {
      const handle = fn(group, prim.params);
      primitiveHandles.push(handle);
    }
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    tl.kill();
    for (const h of primitiveHandles) {
      h?.cleanup?.();
    }
    group.remove(headline);
    for (const disposeFn of disposables) {
      try {
        disposeFn();
      } catch (e) {
        /* noop */
      }
    }
    if (loadedTexture) {
      loadedTexture.dispose?.();
    }
  };

  return group;
}
